Write an async JavaScript arrow function that calls the jev namespace and returns JSON within 12,000 characters. Use jev.evaluate for independent questions over one state; use sequential calls only when an earlier answer changes the next state, options or question. JavaScript handles loops, arithmetic and filtering. Include none/unknown when a choice may not fit; a relative winner is not applicability. Missing confidence requires review in gated procedures. Choose thresholds from labeled development cases and freeze them before held-out evaluation; no universal cutoff is calibrated. Validate returned IDs and source spans in code. Each method uses this connection's scope and allowance. At most 8 method calls, 8 underlying model attempts and 10 seconds per execution; logs and tree share that model budget. Await every call; unfinished work is cancelled when the program returns. No retries, network, actions or credentials. Results are probabilities or rubric scores, not verdicts.

type State = string | Record<string,unknown> | unknown[]; // at most 12,000 serialized characters
type Caller = {callerModel?:string; reasoningEffort?:string};
type Decision<T> = {value:T; requestId?:string; meta:{model?:string; calls?:number; inputTokens?:number; outputTokens?:number; latencyMs?:number; cached?:boolean}; recipe?:unknown};
declare const jev: {
  noul(input: Caller & {state: State; instructions: string; criteria?: {true: string; false: string}}): Promise<Decision<{probability: number}>>; // P(true), not a verdict
  choice(input: Caller & {state: State; instructions: string; criteria: Record<string,string>}): Promise<Decision<{choice: string; probabilities?: Record<string,number>; selectedProbability: number|null; confidence: number|null}>>; // include an explicit none/unknown option when needed
  score(input: Caller & {state: State; instructions: string; criteria: string[]}): Promise<Decision<{score: number; confidence: number|null}>>; // ordered rubric; score may be fractional
  evaluate(input: Caller & {state: State; questions: Record<string, {type: 'noul'; instructions: string; criteria?: {true: string; false: string}} | {type: 'choice'; instructions: string; criteria: Record<string,string>} | {type: 'score'; instructions: string; criteria: string[]}>}): Promise<Decision<{answers: Record<string,unknown>}>>; // 1–8 independent questions over one state
  check(input: Caller & {claim: string; evidence: string | Array<{id:string; text:string}>}): Promise<Decision<{supported: number|null; contradicted: number|null; contradictedBy?: {id:string|null; probability:number|null}}>>;
  find(input: Caller & {question: string; sources: Array<{id:string; text:string}>}): Promise<Decision<{ranking: Array<{id:string; probability:number}>; answerExists: number|null; conflict: number|null; none: number|null}>>;
  select(input: Caller & {task: string; options: Array<{id:string; description:string}>}): Promise<Decision<{choice: {id:string|null; probability:number|null}; none:number|null; fits:Array<{id:string; probability:number|null}>}>>;
  run(input: Caller & {pattern: "next-tool" | "tool-approval" | "context-relevance" | "clarification" | "evidence-check" | "tool-result" | "change-scope" | "acceptance" | "attention" | "memory-candidate" | "freshness" | "rubric" | "intent" | "palette-match" | "item-match" | "command-match" | "semantic-search" | "entity-match" | "citation-check" | "writing-check" | "text-labels" | "structured-fields" | "diagnostic-test" | "repair-check" | "passage-policy" | "ticket-triage" | "handler-route" | "reply-review" | "payment-review" | "paper-screen" | "duplicate-report" | "computer-next-action" | "computer-target" | "computer-form-ready" | "computer-progress" | "computer-outcome" | "computer-recovery" | "corpus-next-action" | "corpus-candidate-match" | "corpus-grep-triage" | "corpus-evidence-check" | "corpus-query-reformulate"; state: string; candidates?: Record<string,string>}): Promise<Decision<unknown>>; // published recipe IDs only
};

Example: async () => { const r = await jev.noul({state: "Build passed; smoke test absent", instructions: "Was the deployment fully verified?"}); return {pVerified: r.value.probability}; };

